 {view==="archive"&&<section className="ci-archive ci-fade"><div className="ci-kicker">THE THINGS YOU CARRY</div><h1>Fragments of Identity</h1><p className="ci-muted">A record of your own observations, unanswered questions and evolving reflections. Not an assessment of your personality.</p>{!entries.length&&<p>Nothing has been recorded yet. There is no need to hurry.</p>}{entries.map(e=>{const door=doors.find(x=>x.id===e.door);return <article key={e.id} className="ci-entry" style={{"--accent":door?.color} as React.CSSProperties}><div className="ci-kicker">{door?.name} · {e.status==="resolved"?"Considered for now":"Open thought"}</div><h2>{e.fragment||"An unfinished thought"}</h2><p>{e.reflection||door?.reflection}</p><div className="ci-small">Originally recorded {formatDate(e.date)}{e.profile?" · life context preserved":""}</div>{(e.additions||[]).map((a,i)=><div className="ci-revision" key={i}><div className="ci-kicker">{a.kind==="resolution"?"Considered for now":a.kind==="reopened"?"Reopened":"New reflection"}</div><div className="ci-small">{formatDate(a.date)} · {Math.floor((new Date(a.date).getTime()-new Date(e.date).getTime())/86400000)} days since first recorded</div><p>{a.text}</p></div>)}<button className="ci-primary" onClick={()=>{setEditing(e.id);setAddition("");setAdditionKind(e.status==="resolved"?"reopened":"addition")}}>Return to this thought ↗</button>{editing===e.id&&<div className="ci-revision"><p>What has changed, if anything, since you first recorded this?</p><textarea value={addition} onChange={ev=>setAddition(ev.target.value)} placeholder="Add a thought, reconsider your interpretation, or describe what happened in between." rows={5}/><label className="ci-label">How would you describe this reflection?<select value={additionKind} onChange={ev=>setAdditionKind(ev.target.value as Addition["kind"])}><option value="addition">Adding to the thought</option><option value="resolution">Considered for now</option><option value="reopened">Reopening or reconsidering</option></select></label><button className="ci-primary" disabled={!addition.trim()} onClick={()=>addToEntry(e.id)}>Preserve this reflection</button><button className="ci-link" onClick={()=>setEditing(null)}>Cancel</button></div>}<button className="ci-link" onClick={()=>setExpanded(expanded===e.id?null:e.id)}>{expanded===e.id?"Hide original reflections":"Read original reflections"}</button>{expanded===e.id&&<div>{e.answers.map((a,i)=>a&&<p key={i} className="ci-original"><small>{i===3?"Examination":door?.prompts[i]}</small><br/>{a}</p>)}<button className="ci-link" onClick={()=>{if(confirm("Delete this visit from this browser?"))setEntries(old=>old.filter(x=>x.id!==e.id))}}>Delete this visit</button></div>}</article>})}<div className="ci-actions"><button className="ci-link" onClick={exportData}>Export my reflections</button><button className="ci-link" onClick={()=>{if(confirm("Delete all saved visits from this browser?"))setEntries([])}}>Delete all visits</button></div><button className="ci-primary" onClick={()=>setView("hub")}>Return to the brain ↗</button></section>}
